window.docContents[141].resolve({"/rules/PL1006/#PL1006-rationale":{"contents":"A positive proof surface must consist of kernel-checked definitions. Unsafe and partial code can be executed, but it cannot serve as logical evidence, and reasoning about it silently depends on its runtime behavior.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1006: Unsafe and partial declarations require exact helper authentication","header":"Why it matters","id":"/rules/PL1006/#PL1006-rationale"},"/rules/PL2005/#PL2005-rationale":{"contents":"Successful elaboration alone is not checked admission: metaprograms and debug options can store declarations the kernel never checked. An accepted result must rest on kernel-checked evidence for the exact frozen sources.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2005: Required admission and source evidence must be complete","header":"Why it matters","id":"/rules/PL2005/#PL2005-rationale"},"/rules/PL4003/#PL4003-rationale":{"contents":"A negative example documents what Lean rejects. If it stops failing, or fails for another reason, the documentation claims a rejection that no longer holds.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL4003: Negative examples require completed intended rejection","header":"Why it matters","id":"/rules/PL4003/#PL4003-rationale"},"/rules/PL5002/#PL5002-rationale":{"contents":"A material claim must be readable without reconstructing it from the proof: the docstring states what the declaration establishes and under which assumptions, and binds the written intent to that exact declaration.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL5002: Registered public material declarations require docstrings","header":"Why it matters","id":"/rules/PL5002/#PL5002-rationale"}});